<student_code untrusted="true">
=== submission_10.ino ===
   1| // Lab 3 - Hardware PWM
   2| // D5 (P1.13), 1 kHz, 25 % duty, NRF_PWM0
   3| //
   4| // PWM clock  : 16 MHz / 16 (DIV_16)  = 1 MHz
   5| // COUNTERTOP : 1 MHz / 1 kHz         = 1000
   6| // compare    : 25 % of 1000          = 250
   7| // polarity   : bit 15 set so 250 is the high time
   8| 
   9| #include <Arduino.h>
  10| 
  11| static uint16_t seq[1] = { 250 | 0x8000 };
  12| 
  13| void setup() {
  14|   NRF_PWM0->PSEL.OUT[0] = (1 << PWM_PSEL_OUT_PORT_Pos) | (13 << PWM_PSEL_OUT_PIN_Pos);
  15|   NRF_PWM0->ENABLE      = PWM_ENABLE_ENABLE_Enabled << PWM_ENABLE_ENABLE_Pos;
  16|   NRF_PWM0->MODE        = PWM_MODE_UPDOWN_Up << PWM_MODE_UPDOWN_Pos;
  17|   NRF_PWM0->PRESCALER   = PWM_PRESCALER_PRESCALER_DIV_16 << PWM_PRESCALER_PRESCALER_Pos;
  18|   NRF_PWM0->COUNTERTOP  = 1000;
  19|   NRF_PWM0->LOOP        = 0;
  20|   NRF_PWM0->DECODER     = (PWM_DECODER_LOAD_Common << PWM_DECODER_LOAD_Pos) |
  21|                           (PWM_DECODER_MODE_RefreshCount << PWM_DECODER_MODE_Pos);
  22|   NRF_PWM0->SEQ[0].PTR      = (uint32_t)seq;
  23|   NRF_PWM0->SEQ[0].CNT      = 1;
  24|   NRF_PWM0->SEQ[0].REFRESH  = 0;
  25|   NRF_PWM0->SEQ[0].ENDDELAY = 0;
  26|   NRF_PWM0->TASKS_SEQSTART[0] = 1;
  27| }
  28| 
  29| void loop() {
  30| }
</student_code>
